7	import { exec, execSync, spawn, spawnSync } from 'node:child_process';
8	import { promisify } from 'node:util';
9	import { once } from 'node:events';
10	import { debugLogger } from './debugLogger.js';
11	import { coreEvents, CoreEvent, type EditorSelectedPayload } from './events.js';
