13	const GUI_EDITORS = [
14	  'vscode',
15	  'vscodium',
16	  'windsurf',
17	  'cursor',
18	  'zed',
19	  'antigravity',
20	] as const;
21	const TERMINAL_EDITORS = ['vim', 'neovim', 'emacs', 'hx'] as const;
22	const EDITORS = [...GUI_EDITORS, ...TERMINAL_EDITORS] as const;
23	
24	const GUI_EDITORS_SET = new Set<string>(GUI_EDITORS);
25	const TERMINAL_EDITORS_SET = new Set<string>(TERMINAL_EDITORS);
26	const EDITORS_SET = new Set<string>(EDITORS);
27	
28	export const NO_EDITOR_AVAILABLE_ERROR =
29	  'No external editor is available. Please run /editor to configure one.';
30	
31	export const DEFAULT_GUI_EDITOR: GuiEditorType = 'vscode';
32	
33	export type GuiEditorType = (typeof GUI_EDITORS)[number];
34	export type TerminalEditorType = (typeof TERMINAL_EDITORS)[number];
35	export type EditorType = (typeof EDITORS)[number];
36	
37	export function isGuiEditor(editor: EditorType): editor is GuiEditorType {
38	  return GUI_EDITORS_SET.has(editor);
39	}
40	
41	export function isTerminalEditor(
42	  editor: EditorType,
43	): editor is TerminalEditorType {
44	  return TERMINAL_EDITORS_SET.has(editor);
45	}
46	
47	export const EDITOR_DISPLAY_NAMES: Record<EditorType, string> = {
48	  vscode: 'VS Code',
49	  vscodium: 'VSCodium',
50	  windsurf: 'Windsurf',
51	  cursor: 'Cursor',
52	  vim: 'Vim',
53	  neovim: 'Neovim',
54	  zed: 'Zed',
55	  emacs: 'Emacs',
56	  antigravity: 'Antigravity',
57	  hx: 'Helix',
58	};
59	
60	export function getEditorDisplayName(editor: EditorType): string {
61	  return EDITOR_DISPLAY_NAMES[editor] || editor;
62	}
63	
64	function isValidEditorType(editor: string): editor is EditorType {
65	  return EDITORS_SET.has(editor);
66	}
67	
68	/**
69	 * Escapes a string for use in an Emacs Lisp string literal.
70	 * Wraps in double quotes and escapes backslashes and double quotes.
71	 */
72	function escapeELispString(str: string): string {
73	  return `"${str.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
74	}
75	
76	interface DiffCommand {
77	  command: string;
78	  args: string[];
79	}
80	
81	const execAsync = promisify(exec);
82	
83	function getCommandExistsCmd(cmd: string): string {
84	  return process.platform === 'win32'
85	    ? `where.exe ${cmd}`
86	    : `command -v ${cmd}`;
87	}
88	
89	function commandExists(cmd: string): boolean {
90	  try {
91	    execSync(getCommandExistsCmd(cmd), { stdio: 'ignore' });
92	    return true;
93	  } catch {
94	    return false;
95	  }
96	}
97	
98	async function commandExistsAsync(cmd: string): Promise<boolean> {
99	  try {
100	    await execAsync(getCommandExistsCmd(cmd));
101	    return true;
102	  } catch {
103	    return false;
104	  }
105	}
106	
107	/**
108	 * Editor command configurations for different platforms.
109	 * Each editor can have multiple possible command names, listed in order of preference.
110	 */
111	const editorCommands: Record<
112	  EditorType,
113	  { win32: string[]; default: string[] }
114	> = {
115	  vscode: { win32: ['code.cmd'], default: ['code'] },
116	  vscodium: { win32: ['codium.cmd'], default: ['codium'] },
117	  windsurf: { win32: ['windsurf'], default: ['windsurf'] },
118	  cursor: { win32: ['cursor'], default: ['cursor'] },
119	  vim: { win32: ['vim'], default: ['vim'] },
120	  neovim: { win32: ['nvim'], default: ['nvim'] },
121	  zed: { win32: ['zed'], default: ['zed', 'zeditor'] },
122	  emacs: { win32: ['emacs.exe'], default: ['emacs'] },
123	  antigravity: {
124	    win32: ['agy.cmd', 'antigravity.cmd', 'antigravity'],
125	    default: ['agy', 'antigravity'],
126	  },
127	  hx: { win32: ['hx'], default: ['hx'] },
128	};
129	
130	function getEditorCommands(editor: EditorType): string[] {
131	  const commandConfig = editorCommands[editor];
132	  return process.platform === 'win32'
133	    ? commandConfig.win32
134	    : commandConfig.default;
135	}
136	
137	export function hasValidEditorCommand(editor: EditorType): boolean {
138	  return getEditorCommands(editor).some((cmd) => commandExists(cmd));
139	}
140	
141	export async function hasValidEditorCommandAsync(
142	  editor: EditorType,
143	): Promise<boolean> {
144	  return Promise.any(
145	    getEditorCommands(editor).map((cmd) =>
146	      commandExistsAsync(cmd).then((exists) => exists || Promise.reject()),
147	    ),
148	  ).catch(() => false);
149	}
150	
151	export function getEditorCommand(editor: EditorType): string {
152	  const commands = getEditorCommands(editor);
153	  return (
154	    commands.slice(0, -1).find((cmd) => commandExists(cmd)) ||
155	    commands[commands.length - 1]
156	  );
157	}
158	
159	export function allowEditorTypeInSandbox(editor: EditorType): boolean {
160	  const notUsingSandbox = !process.env['SANDBOX'];
161	  if (isGuiEditor(editor)) {
162	    return notUsingSandbox;
163	  }
164	  // For terminal-based editors like vim and emacs, allow in sandbox.
165	  return true;
166	}
167	
168	function isEditorTypeAvailable(
169	  editor: string | undefined,
170	): editor is EditorType {
171	  return (
172	    !!editor && isValidEditorType(editor) && allowEditorTypeInSandbox(editor)
173	  );
174	}
175	
176	/**
177	 * Check if the editor is valid and can be used.
178	 * Returns false if preferred editor is not set / invalid / not available / not allowed in sandbox.
179	 */
180	export function isEditorAvailable(editor: string | undefined): boolean {
181	  return isEditorTypeAvailable(editor) && hasValidEditorCommand(editor);
182	}
183	
184	/**
185	 * Check if the editor is valid and can be used.
186	 * Returns false if preferred editor is not set / invalid / not available / not allowed in sandbox.
187	 */
188	export async function isEditorAvailableAsync(
189	  editor: string | undefined,
190	): Promise<boolean> {
191	  return (
192	    isEditorTypeAvailable(editor) && (await hasValidEditorCommandAsync(editor))
193	  );
194	}
195	
196	/**
197	 * Resolves an editor to use for external editing without blocking the event loop.
198	 * 1. If a preferred editor is set and available, uses it.
199	 * 2. If no preferred editor is set (or preferred is unavailable), requests selection from user and waits for it.
200	 */
201	export async function resolveEditorAsync(
202	  preferredEditor: EditorType | undefined,
203	  signal?: AbortSignal,
204	): Promise<EditorType | undefined> {
205	  if (preferredEditor && (await isEditorAvailableAsync(preferredEditor))) {
206	    return preferredEditor;
207	  }
208	
209	  coreEvents.emit(CoreEvent.RequestEditorSelection);
210	
211	  return (
212	    once(coreEvents, CoreEvent.EditorSelected, { signal })
213	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
214	      .then(([payload]) => (payload as EditorSelectedPayload).editor)
215	      .catch(() => undefined)
216	  );
217	}
