228	    return null;
229	  }
230	  const command = getEditorCommand(editor);
231	
232	  switch (editor) {
233	    case 'vscode':
234	    case 'vscodium':
235	    case 'windsurf':
236	    case 'cursor':
237	    case 'zed':
238	    case 'antigravity':
239	      return { command, args: ['--wait', '--diff', oldPath, newPath] };
240	    case 'vim':
241	    case 'neovim':
242	      return {
243	        command,
244	        args: [
245	          '-d',
246	          // skip viminfo file to avoid E138 errors
247	          '-i',
248	          'NONE',
249	          // make the left window read-only and the right window editable
