7	import React, { useContext, useMemo, useSyncExternalStore } from 'react';
8	import type {
9	  LoadableSettingScope,
10	  LoadedSettings,
11	  LoadedSettingsSnapshot,
12	  SettingsFile,
13	} from '../../config/settings.js';
14	import { SettingScope } from '../../config/settings.js';
15	import { checkExhaustive } from '@google/gemini-cli-core';
16	
17	export const SettingsContext = React.createContext<LoadedSettings | undefined>(
18	  undefined,
19	);
20	
21	export const useSettings = (): LoadedSettings => {
22	  const context = useContext(SettingsContext);
23	  if (context === undefined) {
24	    throw new Error('useSettings must be used within a SettingsProvider');
25	  }
26	  return context;
27	};
28	
29	export interface SettingsState extends LoadedSettingsSnapshot {
30	  forScope: (scope: LoadableSettingScope) => SettingsFile;
31	}
32	
33	export interface SettingsStoreValue {
34	  settings: SettingsState;
35	  setSetting: (
36	    scope: LoadableSettingScope,
37	    key: string,
38	    value: unknown,
39	  ) => void;
40	}
41	
42	// Components that call this hook will re render when a settings change event is emitted
43	export const useSettingsStore = (): SettingsStoreValue => {
44	  const store = useContext(SettingsContext);
45	  if (store === undefined) {
46	    throw new Error('useSettingsStore must be used within a SettingsProvider');
47	  }
48	
49	  // React passes a listener fn into the subscribe function
50	  // When the listener runs, it re renders the component if the snapshot changed
51	  const snapshot = useSyncExternalStore(
52	    (listener) => store.subscribe(listener),
53	    () => store.getSnapshot(),
54	  );
55	
56	  const settings: SettingsState = useMemo(
57	    () => ({
58	      ...snapshot,
59	      forScope: (scope: LoadableSettingScope) => {
60	        switch (scope) {
61	          case SettingScope.User:
62	            return snapshot.user;
63	          case SettingScope.Workspace:
64	            return snapshot.workspace;
65	          case SettingScope.System:
66	            return snapshot.system;
67	          case SettingScope.SystemDefaults:
68	            return snapshot.systemDefaults;
69	          default:
70	            checkExhaustive(scope);
71	        }
72	      },
73	    }),
74	    [snapshot],
75	  );
76	
77	  return useMemo(
78	    () => ({
79	      settings,
80	      setSetting: (scope: LoadableSettingScope, key: string, value: unknown) =>
81	        store.setValue(scope, key, value),
82	    }),
83	    [settings, store],
84	  );
85	};
