18	/**
19	 * Opens a file in an external editor and waits for it to close.
20	 * Handles raw mode switching to ensure the editor can interact with the terminal.
21	 *
22	 * @param filePath Path to the file to open
23	 * @param stdin The stdin stream from Ink/Node
24	 * @param setRawMode Function to toggle raw mode
25	 * @param preferredEditorType The user's preferred editor from config
26	 */
27	export async function openFileInEditor(
28	  filePath: string,
29	  stdin: ReadStream | null | undefined,
30	  setRawMode: ((mode: boolean) => void) | undefined,
31	  preferredEditorType?: EditorType,
32	): Promise<void> {
33	  let command: string | undefined = undefined;
34	  const args = [filePath];
35	
36	  if (preferredEditorType) {
37	    command = getEditorCommand(preferredEditorType);
38	    if (isGuiEditor(preferredEditorType)) {
39	      args.unshift('--wait');
40	    }
41	  }
42	
43	  if (!command) {
44	    command = process.env['VISUAL'] ?? process.env['EDITOR'];
45	    if (command) {
46	      const lowerCommand = command.toLowerCase();
47	      const isGui = ['code', 'cursor', 'subl', 'zed', 'atom'].some((gui) =>
48	        lowerCommand.includes(gui),
49	      );
50	      if (
51	        isGui &&
52	        !lowerCommand.includes('--wait') &&
53	        !lowerCommand.includes('-w')
54	      ) {
55	        args.unshift(lowerCommand.includes('subl') ? '-w' : '--wait');
56	      }
57	    }
58	  }
59	
60	  if (!command) {
61	    command = process.platform === 'win32' ? 'notepad' : 'vi';
62	  }
63	
64	  const [executable = '', ...initialArgs] = command.split(' ');
65	
66	  // Determine if we should use sync or async based on the command/editor type.
67	  // If we have a preferredEditorType, we can check if it's a terminal editor.
68	  // Otherwise, we guess based on the command name.
69	  const terminalEditors = ['vi', 'vim', 'nvim', 'emacs', 'hx', 'nano'];
70	  const isTerminal = preferredEditorType
71	    ? isTerminalEditor(preferredEditorType)
72	    : terminalEditors.some((te) => executable.toLowerCase().includes(te));
73	
74	  if (
75	    isTerminal &&
76	    (executable.includes('vi') ||
77	      executable.includes('vim') ||
78	      executable.includes('nvim'))
79	  ) {
80	    // Pass -i NONE to prevent E138 'Can't write viminfo file' errors in restricted environments.
81	    args.unshift('-i', 'NONE');
82	  }
83	
84	  const wasRaw = stdin?.isRaw ?? false;
85	  setRawMode?.(false);
86	
87	  try {
88	    if (isTerminal) {
89	      const result = spawnSync(executable, [...initialArgs, ...args], {
90	        stdio: 'inherit',
91	        shell: process.platform === 'win32',
92	      });
93	      if (result.error) {
94	        coreEvents.emitFeedback(
95	          'error',
96	          '[editorUtils] external terminal editor error',
97	          result.error,
98	        );
99	        throw result.error;
100	      }
101	      if (typeof result.status === 'number' && result.status !== 0) {
102	        const err = new Error(
103	          `External editor exited with status ${result.status}`,
104	        );
105	        coreEvents.emitFeedback(
106	          'error',
107	          '[editorUtils] external editor error',
108	          err,
109	        );
110	        throw err;
111	      }
112	    } else {
113	      await new Promise<void>((resolve, reject) => {
114	        const child = spawn(executable, [...initialArgs, ...args], {
115	          stdio: 'inherit',
116	          shell: process.platform === 'win32',
117	        });
118	
119	        child.on('error', (err) => {
120	          coreEvents.emitFeedback(
121	            'error',
122	            '[editorUtils] external editor spawn error',
123	            err,
124	          );
125	          reject(err);
126	        });
127	
128	        child.on('close', (status) => {
129	          if (typeof status === 'number' && status !== 0) {
130	            const err = new Error(
131	              `External editor exited with status ${status}`,
132	            );
133	            coreEvents.emitFeedback(
134	              'error',
135	              '[editorUtils] external editor error',
136	              err,
137	            );
138	            reject(err);
139	          } else {
140	            resolve();
141	          }
142	        });
143	      });
144	    }
145	  } finally {
146	    if (wasRaw) {
147	      setRawMode?.(true);
148	    }
149	    coreEvents.emit(CoreEvent.ExternalEditorClosed);
150	  }
151	}
